// src/index.js
import "./App.scss";
import "./Button.scss";
import "./Responsive1500.scss";
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { worker } from "./mocks/browser";
import { FRONT_BASE } from "./api/config";

(async function bootstrap() {
  // FRONT_BASE 예: "/woodenpages" 또는 "/"
  const base  = (FRONT_BASE || "/").replace(/\/+$/,""); // 끝 슬래시 제거
  const scope = `${base}/`;                             // 스코프는 슬래시로 끝나야 함
  const url   = `${scope}mockServiceWorker.js`;         // 워커 파일 경로

  try {
    await worker.start({
      serviceWorker: { url, options: { scope } },
      onUnhandledRequest: "error",                      
    });
    console.log("[MSW] registered:", { url, scope });
  } catch (e) {
    console.warn("[MSW] failed to register:", e?.message || e);
  }

  const root = ReactDOM.createRoot(document.getElementById("root"));
  root.render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
})();
